def is_currency_unit(unit) -> bool:
    """True if *unit* (a pint Unit/Quantity) is a bovnar currency.

    Detected via the ``[currency_`` dimension-name prefix, so it holds for any
    power/product that involves a currency (e.g. USD/year).
    """
    return any(str(k).startswith('[currency_') for k in unit.dimensionality)


def build_registry(reg=None, *, with_currencies: bool = True,
                   isolate_kinds: bool = True):
    """Return a pint UnitRegistry with bovnar's custom units registered.

    Pass an existing registry to extend it, or None to create a fresh one.
    Set with_currencies=False to skip the 216 currency dimensions (e.g. when
    the caller prefers to reject currency-typed data in the pint path).

    isolate_kinds (default True) gives every bovnar quantity kind its own pint
    dimension, so pint refuses exactly the conversions bovnar refuses: an NTU
    will not become an FNU, a byte will not become 8 bits, an angle will not
    become a plain number. Conversions *within* a kind keep working. Set it to
    False to alias those units onto pint's natives instead — a bovnar byte then
    converts to pint's `megabyte`, and pint also allows the conversions bovnar
    calls unsound. That trade is the caller's to make; the default is fidelity.
    """
    import pint
    if reg is None:
        reg = pint.UnitRegistry()
    for d in BOVNAR_PINT_DEFINITIONS:
        reg.define(d)
    if isolate_kinds:
        for name, dim in KIND_DIMENSIONS.items():
            reg.define('%s = [%s]' % (name, dim))
        for d in _ANGLE_DERIVED:
            reg.define(d)
        for d in _INTERVAL_DERIVED:
            reg.define(d)
    else:
        for d in _KIND_NATIVE_FALLBACK:
            reg.define(d)
    if with_currencies:
        for d in CURRENCY_DEFINITIONS:
            reg.define(d)
    return reg


def is_kind_scale(unit) -> bool:
    """True if *unit* carries one of bovnar's isolated quantity kinds.

    Only meaningful for a registry built with isolate_kinds=True (the default);
    with the natives aliased back in there is nothing to detect.
    """
    dims = getattr(unit, 'dimensionality', unit)
    wanted = set(KIND_DIMENSIONS.values())
    return any(str(name).strip('[]') in wanted for name in dims)
